import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";

/**
 * Scheduled-backup sweep.
 *
 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
 * (`autoBackup=true`) whose last automatic backup is older than their configured
 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
 * each — de-duping on any in-flight job so it's safe to call on a timer.
 *
 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
 *
 *   import { scheduledBackupSweep } from "./backup-schedule";
 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
 *     lastBackupSweep = Date.now();
 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
 *   }
 */
export async function scheduledBackupSweep(): Promise<void> {
  if (SANDBOX) return; // no real backups run in the sandbox
  const now = Date.now();

  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoBackup: true,
      backupIntervalHours: { not: null },
    },
    select: {
      id: true,
      hostname: true,
      backupIntervalHours: true,
      lastAutoBackup: true,
    },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const intervalMs = (s.backupIntervalHours ?? 0) * 60 * 60_000;
    if (intervalMs <= 0) continue;

    // Due if it has never run, or the cadence has elapsed since the last one.
    const dueAt = s.lastAutoBackup ? s.lastAutoBackup.getTime() + intervalMs : 0;
    if (now < dueAt) continue;

    // Respect the one-in-flight-job-per-server invariant.
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;

    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
    // Mark the schedule as satisfied now so a slow backup / a second sweep pass
    // doesn't pile up duplicate jobs; the timestamp anchors the next window.
    await db.server.update({
      where: { id: s.id },
      data: { lastAutoBackup: new Date() },
    });
    enqueued++;
  }

  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
}
