/**
 * Host gate: the admin portal is only reachable from the dedicated admin
 * hostname(s) in NXEON_ADMIN_HOSTS (comma-separated). On any other host — e.g.
 * the public nxeon.cloud — /admin 404s as if it doesn't exist. Empty/unset =
 * no host restriction (dev fallback). Returns true when access should be REFUSED.
 */
async function adminHostBlocked(): Promise<boolean> {
  const allow = (process.env.NXEON_ADMIN_HOSTS ?? "")
    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
  if (allow.length === 0) return false;
  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
  return !allow.includes(host);
}
import { realUser, impersonating } from "@/lib/auth";
import { isStaff, canAccessHref } from "@/lib/rbac";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { Shell, type NavSection } from "@/components/portal/Shell";
import { ADMIN_NAV } from "@/lib/admin-groups";
import { AdminSubTabs } from "@/components/admin/SubTabs";

/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
function isPlainIp(s: string): boolean {
  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
}

/**
 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
 * parseable entries or the requester IP can't be determined, so a bad value can
 * never lock every admin out — only an exact match is ever enforced.
 * Returns true when access should be REFUSED.
 */
async function adminIpBlocked(): Promise<boolean> {
  const raw = await getSetting("allowed_admin_ips", "");
  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
  if (entries.length === 0) return false; // no restriction configured
  const valid = entries.filter(isPlainIp);
  if (valid.length === 0) {
    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
    return false; // malformed -> fail open
  }
  const hdrs = await headers();
  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
  // client-supplied leftmost entry.
  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
  if (!ip) {
    console.warn("[admin-ip] could not determine requester IP; failing open");
    return false;
  }
  return !valid.includes(ip);
}

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
  if (await adminHostBlocked()) notFound();

  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  const imp = await impersonating();
  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools

  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
  if (await adminIpBlocked()) {
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "0.75rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
          The admin console isn&apos;t available from your current network.
        </p>
      </main>
    );
  }

  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
  // using admin tools. Redirect (don't hard-fail) to their security settings so
  // they can enroll, then come back.
  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
    redirect("/dashboard/settings?require2fa=1");
  }

  // Filter every entry's members down to what this role can access, drop entries
  // that end up empty, then drop sections that end up empty. An entry always
  // links to (and its sub-tab bar always starts at) its first *accessible*
  // member, so no role is ever handed a link that just bounces it to /admin.
  const visibleSections = ADMIN_NAV.map((section) => ({
    ...section,
    entries: section.entries
      .map((entry) => ({
        ...entry,
        tabs: entry.tabs.filter((tab) => canAccessHref(user.role, tab.href)),
      }))
      .filter((entry) => entry.tabs.length > 0),
  })).filter((section) => section.entries.length > 0);

  // Flat list of every href this role may reach — handed to <AdminSubTabs /> so
  // the in-page tab bars hide the same members the sidebar does.
  const allowedHrefs = visibleSections.flatMap((s) =>
    s.entries.flatMap((e) => e.tabs.map((t) => t.href))
  );

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
  // missing model/table can never break the admin layout.
  const soft = (p: Promise<number>) => p.catch(() => 0);
  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
    // Live chat: conversations flagged unread for agents (same "needs a reply"
    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
    // Support desk: tickets awaiting a staff reply (open + customer replies),
    // matching the "Awaiting staff" stat on /admin/support.
    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
    // Abuse queue: alerts still OPEN.
    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
    // Feedback: new (untriaged) reports.
    soft(db.feedback.count({ where: { status: "NEW" } })),
    // Improvements board: proposals awaiting the owner's approve/decline.
    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
  ]);

  // Per-route attention counts, unchanged in meaning from the flat sidebar.
  const badges: Record<string, number> = {
    "/admin/chat": chatUnread,
    "/admin/support": ticketsAwaiting,
    "/admin/abuse": abuseOpen,
    "/admin/feedback": feedbackNew,
    "/admin/improvements": improvementsProposed,
  };
  // Build the sidebar: one icon'd row per top-level ENTRY, grouped into labelled
  // sections. Secondary members ride along as `children` — the sidebar never
  // expands them (they're the page's sub-tabs), but they keep the parent row
  // highlighted while you're on one and keep ⌘K able to reach every route.
  // Attention counts ROLL UP: an entry shows the sum of its members' badges, and
  // <AdminSubTabs /> repeats each member's own count on its tab.
  const nav: NavSection[] = visibleSections.map((section) => ({
    label: section.label,
    items: section.entries.map((entry) => {
      const rollup = entry.tabs.reduce((sum, tab) => sum + (badges[tab.href] ?? 0), 0);
      return {
        label: entry.label,
        href: entry.tabs[0].href,
        icon: entry.icon,
        badge: rollup > 0 ? rollup : undefined,
        children: entry.tabs.map((tab) => ({
          label: tab.label,
          href: tab.href,
          badge: badges[tab.href] > 0 ? badges[tab.href] : undefined,
        })),
      };
    }),
  }));

  return (
    <Shell
      nav={nav}
      tag="ops"
      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
    >
      {/* Sub-navigation for the consolidated entries, mounted once here so every
          grouped page gets its tab bar without per-page wiring. Renders nothing
          for single-member entries. */}
      <AdminSubTabs badges={badges} allowed={allowedHrefs} />
      {children}
    </Shell>
  );
}

