/** Every entry across every section, in sidebar order. */
export function adminEntries(): AdminEntry[] {
  return ADMIN_NAV.flatMap((g) => g.entries);
}

/**
 * Does `pathname` belong to `href`? Exact match, or a detail route beneath it
 * (`/admin/users/123`). The bare "/admin" only ever matches exactly so it can
 * never swallow every deeper route.
 */
export function hrefMatches(href: string, pathname: string): boolean {
  if (pathname === href) return true;
  if (href === "/admin") return false;
  return pathname.startsWith(href + "/");
}

/**
 * Resolve which top-level entry owns a given admin pathname, by longest
 * matching member href. Returns null for admin paths outside the IA.
 */
export function entryForPath(pathname: string): AdminEntry | null {
  let best: { entry: AdminEntry; len: number } | null = null;
  for (const entry of adminEntries()) {
    for (const tab of entry.tabs) {
      if (hrefMatches(tab.href, pathname) && (!best || tab.href.length > best.len)) {
        best = { entry, len: tab.href.length };
      }
    }
  }
  return best?.entry ?? null;
}

