export function StatCard({
  label,
  value,
  delta,
  deltaGood,
  spark,
  sparkColor = "#8a70fb",
  icon,
  href,
}: {
  label: string;
  value: string;
  delta?: string;
  deltaGood?: boolean;
  spark?: number[];
  sparkColor?: string;
  icon?: React.ReactNode;
  href?: string;
}) {
  const inner = (
    <div className="card card-hover flex h-full flex-col justify-between p-5">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-[13px] text-slate-400">{label}</p>
          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
          {delta && (
            <p className={`mt-1 text-xs font-medium ${deltaGood === false ? "text-red-400" : "text-emerald-400"}`}>
              {delta}
            </p>
          )}
        </div>
        {icon && (
          <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
            {icon}
          </div>
        )}
      </div>
      {spark && spark.length > 1 && (
        <div className="mt-3">
          <Sparkline data={spark} width={200} height={32} stroke={sparkColor} id={label.replace(/\W/g, "")} />
        </div>
      )}
    </div>
  );
  return href ? <Link href={href}>{inner}</Link> : inner;
}

