async function pveRequestTo(
  base: string,
  token: string,
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  params?: Record<string, string | number | undefined>
): Promise<any> {
  const url = new URL(`${base}/api2/json${path}`);
  let body: string | undefined;
  const headers: Record<string, string> = { Authorization: token };

  const clean = Object.fromEntries(
    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
  ) as Record<string, string>;

  if (method === "GET" || method === "DELETE") {
    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
  } else {
    body = new URLSearchParams(clean as Record<string, string>).toString();
    headers["Content-Type"] = "application/x-www-form-urlencoded";
  }

  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
  const text = await res.text();
  if (!res.ok) {
    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
  }
  try {
    return JSON.parse(text).data;
  } catch {
    return text;
  }
}

function pveRequest(
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  params?: Record<string, string | number | undefined>
) {
  return pveRequestTo(BASE, TOKEN, method, path, params);
}

