/**
 * Retention: keep only the newest `keep` backups for a VM on the backup storage,
 * deleting the older ones (best-effort per file, oldest first). Runs after every
 * successful backup so customer servers never accumulate beyond their limit.
 * Returns how many were deleted.
 */
export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
  const content: any[] = await client.get(`/nodes/${client.node}/storage/backup/content`, { content: "backup" });
  const mine = content
    .filter((b) => b.vmid === vmid && typeof b.volid === "string")
    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
  const toDelete = mine.slice(Math.max(0, keep));
  let deleted = 0;
  for (const b of toDelete) {
    try {
      await deleteBackup(client, b.volid);
      deleted++;
    } catch (e) {
      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
    }
  }
  return deleted;
}

