// ---------------------------------------------------------------------------
// Platform backups vs customer backups
// ---------------------------------------------------------------------------
//
// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
// used to write the platform's own host-level disaster-recovery archives into the
// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
// backups land in, and `pruneBackups` below selected victims with nothing but
// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
// archives — the customer's own manual one from 2026-07-25 12:22 and the
// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
// the platform's copy of their VM. Repeated across the fleet that silently
// destroys the entire bare-metal recovery set, one customer click at a time.
//
// The fix is three independent layers, in order of strength:
//
//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
//     platform archives have no `volid` at all: they cannot appear in the
//     `/storage/backup/content` listing this function iterates, and there is no
//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
//     them. Not "filtered out" — not addressable.
//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
//     storage-content DELETE (whole-repo grep: this file plus its single caller in
//     worker/index.ts). It re-derives protection for every volid immediately
//     before deleting and refuses on any of: the PVE `protected` attribute, the
//     platform notes marker, or the protection registry — and it fails CLOSED if
//     it cannot determine the answer.
//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
//     before layer 1 existed.

/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";

/**
 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
 * notes contain this string.
 */
export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";

/**
 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
 * pre-existing platform archives that were written into the shared storage before
 * the dumpdir split. Anything listed here is undeletable through this module.
 */
const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;

/**
 * Read the protection registry.
 *
 * Returns `null` when the registry exists but could not be read. Callers MUST
 * treat `null` as "protection state unknown" and refuse to delete: a transient
 * EIO on this file must not be the thing that lets a customer's prune wipe the
 * platform's recovery set. A registry that simply does not exist yet (fresh
 * install, platform job has never run) is a legitimate empty set — layer 1 means
 * there is nothing in the shared storage to protect in that case anyway.
 */
async function protectedVolids(): Promise<Set<string> | null> {
  const { readFile } = await import("node:fs/promises");
  try {
    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
    return new Set(
      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
    );
  } catch (e: any) {
    if (e?.code === "ENOENT") return new Set();
    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
    return null;
  }
}

/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
export type StorageBackupEntry = {
  volid?: string;
  vmid?: number;
  ctime?: number;
  size?: number;
  notes?: string;
  protected?: boolean | number;
};

/**
 * Is this archive one of the platform's own (i.e. never customer-prunable)?
 * Any single signal is enough — they are deliberately redundant.
 */
export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
  if (b.protected) return true;
  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
  return false;
}

/**
 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
 *
 * This is the ONLY storage-content DELETE in the codebase, so it is where the
 * "a customer can never delete a platform archive" invariant is enforced rather
 * than merely intended. It re-checks protection against the live hypervisor for
 * the exact volid being deleted — a caller that passed a stale or hand-crafted
 * volid cannot slip past it. Every uncertain outcome throws.
 */
export async function deleteBackup(client: any, volid: string): Promise<void> {
  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
  // anything else keeps a malformed or path-traversing volid from ever reaching
  // the API, and keeps this function honest about what it operates on.
  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);

  const registry = await protectedVolids();
  if (registry === null) {
    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
  }
  if (registry.has(volid)) {
    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
  }

  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
  // here means we do not know whether this is a platform archive, so we stop.
  let info: any;
  try {
    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
  } catch (e) {
    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
  }
  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
  }

  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
}

/**
 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
 * belong to that customer, deleting the older ones (best-effort per file, oldest
 * first). Runs after every successful customer backup, and from the standalone
 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
 *
 * Platform archives are excluded from the delete set AND from the retention
 * count. Counting them would be its own bug: with keep = 2, three platform
 * archives of a vmid would make every customer archive "older than the newest
 * two" and delete all of the customer's backups instead.
 */
export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
  const registry = await protectedVolids();
  if (registry === null) {
    // Fail closed: no retention this pass. Archives accumulating for one cycle is
    // recoverable; deleting the platform's only copy of a VM is not.
    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
    return 0;
  }

  const content: StorageBackupEntry[] = await client.get(
    `/nodes/${client.node}/storage/backup/content`,
    { content: "backup" }
  );
  const forVmid = content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
  const mine = forVmid
    .filter((b) => !isPlatformArchive(b, registry))
    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));

  if (shielded.length > 0) {
    console.log(
      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
    );
  }

  const toDelete = mine.slice(Math.max(0, keep));
  let deleted = 0;
  for (const b of toDelete) {
    try {
      await deleteBackup(client, b.volid!);
      deleted++;
    } catch (e) {
      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
    }
  }
  return deleted;
}
